query.base:
FROM metrics-gcp.cloudsql_postgresql.otel-*
| WHERE gcp.resource_type == "cloudsql_database"
// Only the documents the rule needs: uptime, the engine marker and stopped states.
| WHERE `cloudsql.googleapis.com/database/uptime` IS NOT NULL
     OR `cloudsql.googleapis.com/database/postgresql/num_backends` IS NOT NULL
     OR (`cloudsql.googleapis.com/database/instance_state` == 1 AND attributes.state == "RUNNABLE")
// uptime is a DELTA metric: seconds the instance ran within each 60 s sample. Running
// minutes read 59-61 s. MIN per minute, so a duplicated sample cannot add up past the
// partial-minute threshold.
| EVAL minute = DATE_TRUNC(1 minute, `@timestamp`)
| STATS uptime_s = MIN(`cloudsql.googleapis.com/database/uptime`),
        pg = COUNT(`cloudsql.googleapis.com/database/postgresql/num_backends`),
        stopped = COUNT(*) WHERE `cloudsql.googleapis.com/database/instance_state` == 1 AND attributes.state == "RUNNABLE"
    BY minute, database_id
// The PostgreSQL engine marker covers the whole 1-hour rule window, so the minutes around
// a restart stay in scope.
| INLINE STATS pg_total = SUM(pg),
               last_full = MAX(minute) WHERE uptime_s >= 58,
               first_stopped = MIN(minute) WHERE stopped > 0,
               last_stopped = MAX(minute) WHERE stopped > 0
    BY database_id
| WHERE pg_total > 0
// A start is a partial minute (0 < uptime < 58 s, one second below the healthy 59-61 s
// jitter) followed by at least one full minute.
// A partial minute with no full minute after it is the instance stopping, which the
// instance down rule covers.
| WHERE uptime_s > 0 AND uptime_s < 58 AND minute < last_full
// Signal window: starts in the last 30 minutes (>= 15 min for ingestion delay)
| WHERE minute >= NOW() - 30 minutes
// Owner stop and start: ignore partial minutes within 10 minutes of a stopped (RUNNABLE)
// period. Remove this filter to alert on those starts too.
| WHERE first_stopped IS NULL
     OR minute < first_stopped - 10 minutes
     OR minute > last_stopped + 10 minutes
| STATS restarts = COUNT(*), last_restart = MAX(minute) BY database_id
